let captureRequestId=0;
async function refreshCaptures(){
  const requestId=++captureRequestId;let [status,frames]=await Promise.all([optionalApi('/api/mobile/captures/status'),optionalApi(captureFramesUrl())]);
  if(requestId!==captureRequestId||state.view!=='collector')return;
  if(!frames?.load_error&&Number.isFinite(Number(frames?.total))&&state.captureOffset>0&&state.captureOffset>=Number(frames.total)){state.captureOffset=0;frames=await optionalApi(captureFramesUrl());if(requestId!==captureRequestId||state.view!=='collector')return;}
  state.captureStatusData=status;state.captureFramesData=frames;if($('mobile-capture-panel'))$('mobile-capture-panel').innerHTML=mobileCapturePanel(status,frames);
}

function mobileJobsUrl(){const params=new URLSearchParams({limit:25,offset:state.jobsOffset});if(state.jobsBatch)params.set('batch_id',state.jobsBatch);if(state.jobsCatalog)params.set('catalog_id',state.jobsCatalog);return `/api/mobile/jobs?${params}`;}
